    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    allowed_digits = list(map(int, input[2:2+M]))

    # Match costs for digits 1-9
    cost = [0, 2, 5, 5, 4, 5, 6, 3, 7, 6]

    # Initialize DP array
    dp = [-1] * (N + 1)
    dp[0] = 0

    for i in range(1, N + 1):
        for d in allowed_digits:
            if i >= cost[d]:
                if dp[i - cost[d]] != -1:
                    dp[i] = max(dp[i], dp[i - cost[d]] + 1)

    # Reconstruct the largest number
    result = []
    remaining = N
    while remaining > 0:
        for d in sorted(allowed_digits, reverse=True):
            if cost[d] <= remaining and dp[remaining - cost[d]] == dp[remaining] - 1:
                result.append(str(d))
                remaining -= cost[d]
                break

    print(''.join(result))

if __name__ == "__main__":
