import sys
from functools import lru_cache

def main():
    N, K = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    max_bit = 40  # since K can be up to 1e12, which is 40 bits
    cnt0 = [0] * (max_bit + 1)
    cnt1 = [0] * (max_bit + 1)

    for j in range(max_bit + 1):
        for a in A:
            if (a >> j) & 1:
                cnt1[j] += 1
            else:
                cnt0[j] += 1

    @lru_cache(maxsize=None)
    def dfs(bit, tight):
        if bit < 0:
            return 0
        max_bit_val = (K >> bit) & 1 if tight else 1
        res = 0
        for choice in [0, 1]:
            if choice > max_bit_val:
                continue
            new_tight = tight and (choice == max_bit_val)
            if choice == 0:
                contrib = cnt1[bit] * (1 << bit)
            else:
                contrib = cnt0[bit] * (1 << bit)
            res = max(res, contrib + dfs(bit - 1, new_tight))
        return res

    result = dfs(max_bit, True)
    print(result)

if __name__ == "__main__":
    main()
