import sys

def main():
    N = int(sys.stdin.readline())
    max_a = 37  # since 3^37 is about 4e17, which is less than 1e18
    for a in range(1, max_a + 1):
        pow3 = 3 ** a
        if pow3 >= N:
            break
        r = N - pow3
        if r < 5:
            continue
        temp = r
        b = 0
        while temp % 5 == 0:
            temp //= 5
            b += 1
        if temp == 1:
            print(a, b)
            return
    print(-1)

if __name__ == "__main__":
